-- Pure internal validation, not an externally callable mutation.
-- Only known-caster base choices are covered. Grants, subclass exceptions,
-- edition policy, historical initial choices and preparation need separate validation.
create function public.terravale_validate_known_spell_delta(
 p_class text,p_from integer,p_to integer,p_existing text[],p_add text[],p_remove text[],p_allowed_editions text[]
) returns boolean language plpgsql stable set search_path='' as $validate$
declare prev public.terravale_spell_selection_rules%rowtype; next_rule public.terravale_spell_selection_rules%rowtype;
 final_ids text[]; n_known integer; n_cantrip integer;
begin
 if p_from is null or p_to is null or p_to<>p_from+1 or p_from<1 or p_to>20
 or p_existing is null or p_add is null or p_remove is null or p_allowed_editions is null
 or cardinality(p_existing)>100 or cardinality(p_add)>100 or cardinality(p_remove)>1
 or array_position(p_existing,null) is not null or array_position(p_add,null) is not null or array_position(p_remove,null) is not null
 then return false; end if;
 select * into prev from public.terravale_spell_selection_rules where class_name=p_class and character_level=p_from;
 if not found then return false; end if;
 select * into next_rule from public.terravale_spell_selection_rules where class_name=p_class and character_level=p_to;
 if not found then return false; end if;
 if cardinality(p_remove)>next_rule.replacement_limit or not(p_remove<@p_existing) or p_add&&p_existing then return false; end if;
 if exists(select 1 from unnest(p_remove) x(id) left join public.terravale_spell_selection_catalog s on s.id=x.id where s.id is null or s.level=0) then return false; end if;
 if exists(select 1 from unnest(p_existing) x(id) left join public.terravale_spell_selection_catalog s on s.id=x.id where s.id is null or not(s.classes ? p_class) or s.level>prev.max_spell_level) then return false; end if;
 if (select count(distinct s.identity) from unnest(p_existing) x(id) join public.terravale_spell_selection_catalog s on s.id=x.id)<>cardinality(p_existing) then return false; end if;
 select count(*) filter(where s.level>0),count(*) filter(where s.level=0) into n_known,n_cantrip from unnest(p_existing) x(id) join public.terravale_spell_selection_catalog s on s.id=x.id;
 if n_known<>prev.known_limit or n_cantrip<>prev.cantrip_limit then return false; end if;
 if exists(select 1 from unnest(p_add) x(id) left join public.terravale_spell_selection_catalog s on s.id=x.id where s.id is null or not(s.classes ? p_class) or s.level>next_rule.max_spell_level or not(s.edition=any(p_allowed_editions))) then return false; end if;
 if exists(select 1 from unnest(p_add) a(id) join public.terravale_spell_selection_catalog s on s.id=a.id join public.terravale_spell_selection_catalog old on old.identity=s.identity where old.id=any(p_existing)) then return false; end if;
 select array(select x from unnest(p_existing) x where not(x=any(p_remove)))||p_add into final_ids;
 if (select count(distinct s.identity) from unnest(final_ids) x(id) join public.terravale_spell_selection_catalog s on s.id=x.id)<>cardinality(final_ids) then return false; end if;
 select count(*) filter(where s.level>0),count(*) filter(where s.level=0) into n_known,n_cantrip from unnest(final_ids) x(id) join public.terravale_spell_selection_catalog s on s.id=x.id;
 return n_known=next_rule.known_limit and n_cantrip=next_rule.cantrip_limit;
end $validate$;
revoke all on function public.terravale_validate_known_spell_delta(text,integer,integer,text[],text[],text[],text[]) from public,anon,authenticated;
commit;
